    // std addr round-trip: as_abstract_name strips leading nuls only if
    // the address really is abstract
    assert!(local.as_pathname().is_none());
    println!("bind abstract local_addr: {:?}", local);

    let listener2 = UnixListener::bind("\0/tmp/mesh/mmmeshexample2").unwrap();
    let path = "\0/tmp/mesh/mmmeshexample2";
    let stream = UnixStream::connect(path).await.unwrap();
    let peer = stream.peer_addr().unwrap();
    println!("connect abstract peer_addr: {:?}", peer);
    assert!(peer.as_pathname().is_none());
    drop(stream);

    let (s, _) = listener.accept().await.unwrap();
    println!("accepted: {:?}", s.peer_addr().unwrap());
    drop(listener2);

    let dir = std::env::temp_dir().join("abscheck_regular");
    let _ = std::fs::remove_file(&dir);
    let l3 = UnixListener::bind(&dir).unwrap();
    assert!(l3.local_addr().unwrap().as_pathname().is_some());
    println!("bind pathname ok");

    // verify with netstat-equivalent: read /proc/net/unix
    let proc = std::fs::read_to_string("/proc/net/unix").unwrap();
    let found = proc
        .lines()
        .any(|l| l.contains("@/tmp/mesh/mmmeshexample") && !l.contains("@@/tmp"));
    assert!(found, "abstract socket not listed correctly in /proc/net/unix");
    println!("proc/net/unix check ok");
}

